    // App: ECL | Module: ECL Data Entry (FunctionId 555)
    [HttpGet]
    public async Task<IActionResult> AddSchemeOutlay(int? demandId, int? categoryId, int? rowId, CancellationToken ct)
    {
        ViewData["Title"] = "Add Scheme Outlay";
        ViewData["Breadcrumb"] = "ECL / ECL Data Entry / Add Scheme Outlay";

        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return await ExpiredSessionRedirectAsync();
        }

        if (!session.HasPermission(AddSchemeOutlayFunctionId))
        {
            return Forbid();
        }

        var model = await BuildEntryViewModelAsync(session, demandId, categoryId, ct);

        // Saved grid's Edit column (added 2026-08-18) — reached via ?rowId=X, pre-populates the
        // entry form above from the real row instead of rendering blank. The row must belong to
        // whatever Category was resolved (categoryId, defaulted below if omitted) so the Scheme
        // dropdown already contains it.
        if (rowId.HasValue)
        {
            var outlayResult = await _eclClient.GetOutlayAsync(session.Token, rowId.Value, ct);
            if (outlayResult.IsSuccess && outlayResult.Data != null)
            {
                model.SelectedOutlay = outlayResult.Data;
                model.SelectedCategoryId = outlayResult.Data.CategoryId;
                model.SelectedSchemeId = outlayResult.Data.SchemeId;

                if (outlayResult.Data.DemandId.HasValue && outlayResult.Data.CategoryId.HasValue)
                {
                    var schemesResult = await _eclClient.GetSchemesAsync(session.Token, outlayResult.Data.DemandId.Value, outlayResult.Data.CategoryId.Value, ct);
                    model.Schemes = schemesResult.Data ?? new List<EclSchemeDto>();
                }
            }
        }

        return View(model);
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> AddSchemeOutlay(EclOutlayFormModel form, CancellationToken ct)
    {
        ViewData["Title"] = "Add Scheme Outlay";
        ViewData["Breadcrumb"] = "ECL / ECL Data Entry / Add Scheme Outlay";

        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return await ExpiredSessionRedirectAsync();
        }

        if (!session.HasPermission(AddSchemeOutlayFunctionId))
        {
            return Forbid();
        }

        var request = ToSaveRequest(form, session.FinancialYear);
        var result = form.RowId is > 0
            ? await _eclClient.UpdateOutlayAsync(session.Token, form.RowId.Value, request, ct)
            : await _eclClient.CreateOutlayAsync(session.Token, request, ct);

        var model = await BuildEntryViewModelAsync(session, form.DemandId, form.CategoryId, ct);
        model.StatusIsError = !result.IsSuccess;
        model.StatusMessage = result.IsSuccess
            ? "Scheme outlay saved successfully."
            : result.Error?.Message ?? "Could not save the scheme outlay.";

        return View(model);
    }

    /// <summary>"Send For Approval" button on the saved-outlay grid — single-row action, since
    /// EclOutlayController only exposes a per-row POST {rowId}/submit-for-approval (no bulk
    /// endpoint); the grid posts one row at a time via a per-row form (appendix-actions.js's own
    /// row-scoped pattern), so this matches what the API actually offers rather than inventing a
    /// bulk call the service can't service.</summary>
    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> SendForApproval(int rowId, int demandId, int? categoryId, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return await ExpiredSessionRedirectAsync();
        }

        if (!session.HasPermission(AddSchemeOutlayFunctionId))
        {
            return Forbid();
        }

        var result = await _eclClient.SubmitForApprovalAsync(session.Token, rowId, ct);

        var model = await BuildEntryViewModelAsync(session, demandId, categoryId, ct);
        model.StatusIsError = !result.IsSuccess;
        model.StatusMessage = result.IsSuccess
            ? "Row sent for DOE approval."
            : result.Error?.Message ?? "Could not send this row for approval.";

        ViewData["Title"] = "Add Scheme Outlay";
        ViewData["Breadcrumb"] = "ECL / ECL Data Entry / Add Scheme Outlay";
        return View("AddSchemeOutlay", model);
    }

    /// <summary>Soft-deletes a saved outlay row (grid's Delete column, added 2026-08-18). Same
