    /// <summary>Streams the attached PDF back for the grid's File-icon popup (added 2026-08-18) —
    /// proxies EclOutlayController.GetDocument, same pattern as UploadDocument's proxy the other
    /// direction. GetDocumentAsync buffers into a byte[] (see its own doc comment), which drops the
    /// upstream response headers, so Content-Disposition: inline is set explicitly here rather than
    /// relying on the ECL API's header surviving the hop — the browser needs it to render the PDF
    /// inline in the iframe instead of downloading it, matching the "open in popup" requirement.</summary>
    [HttpGet]
    public async Task<IActionResult> ViewDocument(int rowId, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return await ExpiredSessionRedirectAsync();
        }

        if (!session.HasPermission(AddSchemeOutlayFunctionId))
        {
            return Forbid();
        }

        var result = await _eclClient.GetDocumentAsync(session.Token, rowId, ct);
        if (!result.IsSuccess || result.Data == null)
        {
            return NotFound();
        }

        Response.Headers.ContentDisposition = "inline";
        return File(result.Data, "application/pdf");
    }

    /// <summary>Supporting-PDF upload, forwarded as-is to EclOutlayController's
    /// POST api/ecl/outlay/documents (IFormFile file, demandId, schemeId) — the API is the
    /// authoritative validator (magic-byte check, 5 MB limit); ecl.js's pre-check is UX only.
    /// Returns the StoredFileName as JSON so the entry form can carry it as a hidden field and
    /// submit it back on Save.</summary>
    [HttpPost]
    [ValidateAntiForgeryToken]
    [RequestSizeLimit(6 * 1024 * 1024)]
    public async Task<IActionResult> UploadDocument(IFormFile file, int demandId, int schemeId, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return Unauthorized();
        }

        if (file == null || file.Length == 0)
        {
            return BadRequest(new { message = "No file was supplied." });
        }

        await using var stream = file.OpenReadStream();
        var result = await _eclClient.UploadDocumentAsync(session.Token, stream, file.FileName, file.ContentType, demandId, schemeId, ct);

        return result.IsSuccess
            ? Json(new { success = true, fileName = result.Data!.StoredFileName })
            : Json(new { success = false, message = result.Error?.Message ?? "Upload failed." });
    }

    /// <summary>AJAX helper backing ecl.js's Category->Scheme cascade on AddSchemeOutlay. Client-
    /// corrected 2026-08-20: schemes are scoped by BOTH Demand and Category — Demand is a fixed
    /// hidden field on that page (not user-changeable), so demandId here is always that fixed value,
    /// while categoryId is whatever the user just picked.</summary>
    [HttpGet]
    public async Task<IActionResult> GetSchemes(int demandId, int categoryId, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return Unauthorized();
        }

        var result = await _eclClient.GetSchemesAsync(session.Token, demandId, categoryId, ct);
        return Json(result.Data ?? new List<EclSchemeDto>());
    }

