    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> AddActuals(int rowId, int demandId, int? categoryId, decimal?[] actuals, CancellationToken ct)
    {
        ViewData["Title"] = "Add Actuals";
        ViewData["Breadcrumb"] = "ECL / ECL Data Entry / Add Actuals";

        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return await ExpiredSessionRedirectAsync();
        }

        if (!session.HasPermission(AddActualsFunctionId))
        {
            return Forbid();
        }

        var padded = new decimal?[10];
        for (var i = 0; i < 10 && actuals != null && i < actuals.Length; i++)
        {
            padded[i] = actuals[i];
        }

        var result = await _eclClient.RecordActualsAsync(session.Token, rowId, padded, ct);

        var model = await BuildActualsViewModelAsync(session, demandId, categoryId, rowId, ct);
        model.StatusIsError = !result.IsSuccess;
        model.StatusMessage = result.IsSuccess
            ? "Actuals recorded successfully."
            : result.Error?.Message ?? "Could not record actuals.";

        return View(model);
    }

    /// <summary>
    /// JSON companion to the full-page AddActuals GET/POST above — used by the Add Actuals modal
    /// on AddSchemeOutlay's saved grid (client request 2026-08-18: "avoid unnecessary page
    /// navigation", styled/behaving like the login screen's #changePasswordDialog/
    /// #forgotPasswordDialog). The full-page actions stay as-is for anyone reaching this
    /// FunctionId's route directly (e.g. via the menu) without JS.
    /// </summary>
    [HttpGet]
    public async Task<IActionResult> GetActualsForRow(int rowId, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return Unauthorized();
        }

        if (!session.HasPermission(AddActualsFunctionId))
        {
            return Forbid();
        }

        var result = await _eclClient.GetOutlayAsync(session.Token, rowId, ct);
        if (!result.IsSuccess || result.Data == null)
        {
            return NotFound();
        }

        var outlay = result.Data;
        var schemesResult = await _eclClient.GetSchemesAsync(session.Token, outlay.DemandId ?? 0, outlay.CategoryId ?? 0, ct);
        var schemeName = schemesResult.Data?.FirstOrDefault(s => s.SchemeId == outlay.SchemeId)?.SchemeName ?? $"Scheme #{outlay.SchemeId}";

        return Json(new
        {
            rowId = outlay.RowId,
            financialYear = outlay.FinancialYear,
            schemeName,
            doeApprovalStatusDisplay = outlay.DoeApprovalStatusDisplay,
            outlay = outlay.Outlay,
            actuals = outlay.Actuals
        });
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> SaveActualsAjax(int rowId, decimal?[] actuals, CancellationToken ct)
    {
        var session = HttpContext.Session.GetUbisSession();
        if (session == null)
        {
            return Unauthorized();
        }

        if (!session.HasPermission(AddActualsFunctionId))
        {
            return Forbid();
        }

        var padded = new decimal?[10];
        for (var i = 0; i < 10 && actuals != null && i < actuals.Length; i++)
        {
            padded[i] = actuals[i];
        }

        var result = await _eclClient.RecordActualsAsync(session.Token, rowId, padded, ct);
        if (!result.IsSuccess)
        {
            return BadRequest(new { message = result.Error?.Message ?? "Could not record actuals." });
        }

        return Json(new { success = true });
    }

    private async Task<EclEntryViewModel> BuildEntryViewModelAsync(UbisSessionData session, int? demandId, int? categoryId, CancellationToken ct)
    {
        var model = new EclEntryViewModel
        {
            FinancialYear = session.FinancialYear,
            SelectedCategoryId = categoryId
        };

        var demandsResult = await _aimClient.GetMyDemandsAsync(session.Token, session.FinancialYear, ct);
        var demands = demandsResult.IsSuccess ? demandsResult.Data?.Demands ?? new List<DemandDto>() : new List<DemandDto>();
        var resolvedDemandId = demandId ?? demands.FirstOrDefault()?.DemandId ?? 0;
        var resolvedDemandNo = demandId ?? demands.FirstOrDefault()?.DemandNo ?? 0;

        model.DemandId = resolvedDemandId;
        model.DemandName = demands.FirstOrDefault(d => d.DemandId == resolvedDemandId)?.DemandName ?? string.Empty;
        model.DemandNo = resolvedDemandNo;

        var categoriesResult = await _eclClient.GetCategoriesAsync(session.Token, session.FinancialYear, ct);
        model.Categories = categoriesResult.Data ?? new List<EclCategoryDto>();

        // Client-corrected 2026-08-20: schemes are scoped by BOTH Demand and Category. Demand is
        // always known by this point (resolvedDemandId above) but Category is still a real user
        // selection, so this still waits on it.
        if (categoryId.HasValue)
        {
            var schemesResult = await _eclClient.GetSchemesAsync(session.Token, resolvedDemandId, categoryId.Value, ct);
            model.Schemes = schemesResult.Data ?? new List<EclSchemeDto>();
        }

        var approvalAuthoritiesResult = await _eclClient.GetApprovalAuthoritiesAsync(session.Token, ct);
        model.ApprovalAuthorities = approvalAuthoritiesResult.Data ?? new List<EclApprovalAuthorityDto>();

        var appraiseAuthoritiesResult = await _eclClient.GetAppraiseAuthoritiesAsync(session.Token, ct);
        model.AppraiseAuthorities = appraiseAuthoritiesResult.Data ?? new List<EclAppraiseAuthorityDto>();

        var yearsResult = await _eclClient.GetFinancialYearsAsync(session.Token, ct);
        var years = yearsResult.Data?.FinancialYears ?? new List<string>();
        model.SchemeEndYearOptions = years;
        model.OutlayYearColumns = years;

        var savedResult = await _eclClient.GetOutlaysAsync(session.Token, resolvedDemandId, null, null, session.FinancialYear, ct);
        model.SavedRows = savedResult.Data ?? new List<EclSchemeOutlayDto>();

        return model;
    }

    private async Task<EclActualsViewModel> BuildActualsViewModelAsync(UbisSessionData session, int? demandId, int? categoryId, int? rowId, CancellationToken ct)
    {
        var model = new EclActualsViewModel
        {
            FinancialYear = session.FinancialYear,
            SelectedCategoryId = categoryId,
            SelectedRowId = rowId
        };

        var demandsResult = await _aimClient.GetMyDemandsAsync(session.Token, session.FinancialYear, ct);
        var demands = demandsResult.IsSuccess ? demandsResult.Data?.Demands ?? new List<DemandDto>() : new List<DemandDto>();
        var resolvedDemandId = demandId ?? demands.FirstOrDefault()?.DemandId ?? 0;
        model.DemandId = resolvedDemandId;
        model.DemandName = demands.FirstOrDefault(d => d.DemandId == resolvedDemandId)?.DemandName ?? string.Empty;

        var categoriesResult = await _eclClient.GetCategoriesAsync(session.Token, session.FinancialYear, ct);
        model.Categories = categoriesResult.Data ?? new List<EclCategoryDto>();

        // Client-corrected 2026-08-20: schemes are scoped by both Demand and Category — see the
        // same fix/comment in BuildEntryViewModelAsync above.
        if (categoryId.HasValue)
        {
            var schemesResult = await _eclClient.GetSchemesAsync(session.Token, resolvedDemandId, categoryId.Value, ct);
            model.Schemes = schemesResult.Data ?? new List<EclSchemeDto>();
        }

        // Actuals can only be recorded against rows already submitted (SendToDoe='Y') — mirrors the
        // mockup's Category/Scheme pickers being read-only reference fields, not free entry.
        var submittedResult = await _eclClient.GetOutlaysAsync(session.Token, resolvedDemandId, null, null, session.FinancialYear, ct);
        model.SubmittedRows = (submittedResult.Data ?? new List<EclSchemeOutlayDto>())
            .Where(r => string.Equals(r.SendToDoe, "Y", StringComparison.OrdinalIgnoreCase))
            .ToList();

        if (rowId.HasValue)
        {
            model.SelectedOutlay = model.SubmittedRows.FirstOrDefault(r => r.RowId == rowId.Value)
                ?? (await _eclClient.GetOutlayAsync(session.Token, rowId.Value, ct)).Data;
        }

        return model;
    }

    private static SaveSchemeOutlayRequestDto ToSaveRequest(EclOutlayFormModel form, string financialYear)
    {
        var isYes = string.Equals(form.Is16Fc, "Y", StringComparison.OrdinalIgnoreCase);

        var appraisalAuth = string.Equals(form.AppraisalAuth, "Others", StringComparison.OrdinalIgnoreCase)
            ? form.AppraisalAuthOther
            : form.AppraisalAuth;
        var approveAuth = string.Equals(form.ApproveAuth, "Others", StringComparison.OrdinalIgnoreCase)
            ? form.ApproveAuthOther
            : form.ApproveAuth;

        return new SaveSchemeOutlayRequestDto
        {
            FinancialYear = financialYear,
            CategoryId = form.CategoryId,
            DemandId = form.DemandId,
            SchemeId = form.SchemeId,
            Is16Fc = form.Is16Fc,
            TotalOutlay = form.TotalOutlay,
            CentralShare = isYes ? form.CentralShare : null,
            SchemeEndYear = form.SchemeEndYear,
            AppraisalAuth = appraisalAuth,
            WhetherAppraised = form.WhetherAppraised,
            AppraisalStatusRemarks = form.AppraisalStatusRemarks,
            ApproveAuth = approveAuth,
            IsApproved = form.IsApproved,
            NotApprovedRem = form.NotApprovedRem,
            Outlay = form.Outlay ?? new decimal?[10],
            UserRemarks = form.UserRemarks,
            FileName = form.FileName
        };
    }

    // Client requirement 2026-08-27 ("also make same changes for ECL and SBE modules" - see
    // PreBudgetMeetingController's matching IsAjaxRequest()/ExpiredSessionRedirectAsync): a plain
    // RedirectToAction here was fine for a normal page navigation, but any of ecl.js's own fetch()
    // cascades (Scheme/UmbrellaScheme dropdowns, row lookups, exports) that hit an expired session
    // got a 200 OK with the full Login page's HTML instead of the JSON/blob they expected - caught
    // defensively by those callers' own res.ok/content-type checks (so this wasn't visibly breaking
    // the UI the way PreBudget's container-swap bug did), but still the wrong status code for what
    // actually happened. AJAX requests now get a clean 401 instead.
    private bool IsAjaxRequest() =>
        string.Equals(Request.Headers["X-Requested-With"], "XMLHttpRequest", StringComparison.OrdinalIgnoreCase);

    private async Task<IActionResult> ExpiredSessionRedirectAsync()
    {
        await HttpContext.SignOutAsync(CookieAuthenticationDefaults.AuthenticationScheme);
        if (IsAjaxRequest())
        {
            return Unauthorized();
        }
        return RedirectToAction("Login", "User", new { area = "" });
    }

